      break;
   case 37:
      _left = 1;
      break;
   case 39:
      _right = 1;
}

methods.onKeyup:
switch(param1.keyCode)
{
   case 32:
      _space = 0;
      break;
   case 37:
      _left = 0;
      _leftLong = 0;
      break;
   case 39:
      _right = 0;
      _rightLong = 0;
}

